package dev.navifold.player;
final class NetworkSettings {
 static void show(MainActivity a){NetworkUsage n=NetworkUsage.get(a);android.content.SharedPreferences p=n.prefs;String[] rows={"연결 / 오늘 사용량","데이터 경고 · "+(p.getBoolean("warnings",true)?"ON":"OFF"),"일일 경고 기준 · "+(p.getInt("limitMb",500)==0?"없음":p.getInt("limitMb",500)+" MB"),"요금제 연결 자동 절약 · "+(p.getBoolean("economy",false)?"ON":"OFF"),"MP3 192 kbps로 설정","오늘 집계 초기화"};a.dialog().setTitle("DATA · NETWORK").setItems(rows,(d,w)->{if(w==0)a.info("오늘 사용량",n.summary()+"\n\n전체 값은 이 앱의 UID 수신·송신 카운터로 집계합니다. 모바일/요금제 연결 구분은 5초 간격 추정치이며, 자정·재부팅·VPN/네트워크 전환 때 오차가 있을 수 있습니다. 통신사 청구량과 다르며 사용량 접근 권한은 요구하지 않습니다. 경고는 안내만 하며 재생을 중단하지 않습니다.");if(w==1){p.edit().putBoolean("warnings",!p.getBoolean("warnings",true)).apply();show(a);}if(w==2){int[] values={100,250,500,1000,2000,0};String[] labels={"100 MB","250 MB","500 MB","1 GB","2 GB","경고 없음"};int selected=2;for(int i=0;i<values.length;i++)if(values[i]==p.getInt("limitMb",500))selected=i;a.dialog().setTitle("일일 요금제 연결 경고 기준").setSingleChoiceItems(labels,selected,(x,y)->{p.edit().putInt("limitMb",values[y]).apply();x.dismiss();show(a);}).setNegativeButton("닫기",null).show();}if(w==3){if(p.getBoolean("economy",false)){p.edit().putBoolean("economy",false).apply();show(a);}else a.dialog().setTitle("데이터 자동 절약").setMessage("모바일 또는 요금제 Wi-Fi에서 새로 준비하는 곡을 MP3 최대 192 kbps로 요청합니다(약 86 MB/시간, 음원 데이터 기준). Wi-Fi 무제한 연결에서는 원래 설정을 따릅니다. 이미 준비된 큐와 현재 곡은 유지하므로 새로 재생하거나 큐를 다시 구성해야 적용됩니다. 서버에 인코딩 설정이 필요합니다.").setNegativeButton("취소",null).setPositiveButton("켜기",(x,y)->{p.edit().putBoolean("economy",true).apply();show(a);}).show();}if(w==4){a.settings.original=false;a.settings.bitrate=192;a.original=false;a.settings.save();a.info("스트리밍 음질","MP3 최대 192 kbps로 설정했습니다. 새로 재생하거나 큐에 추가하는 곡부터 적용됩니다. 현재 곡과 기존 큐는 유지됩니다.");}if(w==5)a.dialog().setTitle("오늘 집계 초기화").setMessage("앱 내부 사용량 표시만 초기화합니다.").setNegativeButton("취소",null).setPositiveButton("초기화",(x,y)->{n.reset();show(a);}).show();}).setNegativeButton("닫기",null).show();}
}
